using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = JsonSerializerOptions.Default;

// 1) Strongly-typed retrieval — returns JsonTypeInfo<T> directly
JsonTypeInfo<int[]> arrayInfo = options.GetTypeInfo<int[]>();
Console.WriteLine($"Got typed metadata: {arrayInfo.Type.Name}");

// 2) Probe without throwing — TryGetTypeInfo returns false if unavailable
if (options.TryGetTypeInfo(typeof(string), out JsonTypeInfo? stringInfo))
    Console.WriteLine($"string metadata available: {stringInfo!.Type.Name}");
else
    Console.WriteLine("string metadata NOT available");

// Probe a type that won't be resolvable (custom class, no contract)
var strict = new JsonSerializerOptions { TypeInfoResolver = null };
if (strict.TryGetTypeInfo(typeof(Program), out _))
    Console.WriteLine("Program metadata available");
else
    Console.WriteLine("Program metadata NOT available (no resolver)");

